# Create a minimal WordPress plugin that provides a file upload form
plugin_code = '''<?php
/**
 * Plugin Name: MIFECO File Uploader
 * Description: Temporary file upload utility (DELETE AFTER USE)
 * Version: 1.0
 */
if (!current_user_can('administrator')) return;

add_action('admin_menu', function() {
    add_management_page('Upload Files', 'Upload Files', 'manage_options', 'mifeco-upload', 'mifeco_upload_page');
});

function mifeco_upload_page() {
    if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_FILES['file'])) {
        $target = ABSPATH . $_POST['path'];
        $dir = dirname($target);
        if (!is_dir($dir)) mkdir($dir, 0755, true);
        if (move_uploaded_file($_FILES['file']['tmp_name'], $target)) {
            echo '<div class="notice notice-success"><p>Uploaded to: ' . esc_html($_POST['path']) . '</p></div>';
        } else {
            echo '<div class="notice notice-error"><p>Upload failed</p></div>';
        }
    }
    if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['delete_all'])) {
        $target = ABSPATH . $_POST['del_path'];
        if (is_file($target)) {
            unlink($target);
            echo '<div class="notice notice-success"><p>Deleted: ' . esc_html($_POST['del_path']) . '</p></div>';
        }
    }
    ?>
    <div class="wrap">
        <h1>MIFECO File Uploader</h1>
        <form method="post" enctype="multipart/form-data">
            <table class="form-table">
                <tr><th>File</th><td><input type="file" name="file" required></td></tr>
                <tr><th>Target Path</th><td><input type="text" name="path" value="index.html" style="width:400px"></td></tr>
            </table>
            <p class="submit"><input type="submit" class="button-primary" value="Upload File"></p>
        </form>
        <hr>
        <form method="post">
            <h2>Delete a file</h2>
            <table class="form-table">
