            </table>
            <p class="submit"><input type="submit" name="delete_all" class="button-secondary" value="Delete File"></p>
        </form>
        <hr>
        <p><strong>ABSPATH:</strong> <?= ABSPATH ?></p>
        <p><strong>Theme dir:</strong> <?= get_template_directory() ?></p>
        <p><strong>Upload dir:</strong> <?= wp_upload_dir()['basedir'] ?></p>
    </div>
    <?php
}
'''

